import React, { useEffect, useState } from 'react';
import { Bar, BarChart, CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import AnimatedBackground from '../components/AnimatedBackground';
import FloatingCard from '../components/FloatingCard';
import GlowingIcon from '../components/GlowingIcon';
import { useAuth } from '../context/AuthContext';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';
const demo = { overallCompletion: 42, totalSeconds: 30240, timeByTopic: [{ topic: 'Superposition', seconds: 5400 }, { topic: 'Qubits', seconds: 4200 }, { topic: 'Entanglement', seconds: 3200 }], scoreTrend: [{ topic: 'Qubits', score: 68 }, { topic: 'Superposition', score: 76 }, { topic: 'Gates', score: 84 }, { topic: 'Entanglement', score: 88 }], mastered: [{ topic_slug: 'qubits', best_score: 88 }, { topic_slug: 'gates', best_score: 84 }], needingReview: [{ topic_slug: 'superposition', best_score: 58 }], currentLevel: 'Intermediate', estimatedMinutesRemaining: 245, streak: 12, activity: [], classAverage: 74 };

function label(slug) { return slug.replaceAll('-', ' '); }

export default function AnalyticsPage() {
  const { session, isGuest } = useAuth();
  const [data, setData] = useState(isGuest ? demo : null);
  useEffect(() => { if (!isGuest && session?.accessToken) fetch(`${API_URL}/analytics/dashboard`, { headers: { Authorization: `Bearer ${session.accessToken}` } }).then((response) => response.json()).then(setData).catch(() => setData(demo)); }, [isGuest, session]);
  if (!data) return <main className="analytics-page page-enter"><p className="muted">Loading your learning signals...</p></main>;
  const comparison = data.classAverage ? Math.round((data.scoreTrend.reduce((sum, item) => sum + item.score, 0) / Math.max(data.scoreTrend.length, 1)) - data.classAverage) : 0;
  return <main className="analytics-page page-enter"><AnimatedBackground /><nav className="glass-nav analytics-nav"><a className="brand-mark" href="#learn"><GlowingIcon label="Back to dashboard">←</GlowingIcon> QUANTUM ATLAS</a><div className="nav-links"><a className="nav-link" href="#learn">Dashboard</a><a className="nav-link" aria-current="page" href="#analytics">Analytics</a></div><span className="guest-chip">{isGuest ? 'DEMO DATA' : 'YOUR SIGNALS'}</span></nav><div className="analytics-content"><header className="analytics-hero"><div><p className="eyebrow">Learning telemetry / Personal view</p><h1>See your <span className="text-gradient">momentum.</span></h1><p className="muted">Every experiment adds signal. Here is how your quantum intuition is taking shape.</p></div><div className="streak-orbit"><span>🔥</span><strong>{data.streak} day streak</strong><small>Keep the orbit alive</small></div></header><section className="analytics-stats"><FloatingCard><span className="stat-icon">◒</span><span className="muted">Overall completion</span><strong>{data.overallCompletion}%</strong><div className="progress-track"><div className="progress-fill" style={{ width: `${data.overallCompletion}%` }} /></div></FloatingCard><FloatingCard><span className="stat-icon">◷</span><span className="muted">Time on platform</span><strong>{(data.totalSeconds / 3600).toFixed(1)} <small>hrs</small></strong><span className="success-text">Deep work compounds</span></FloatingCard><FloatingCard><span className="stat-icon">↗</span><span className="muted">Current level</span><strong>{data.currentLevel}</strong><span className="success-text">~{data.estimatedMinutesRemaining} min to next milestone</span></FloatingCard></section><section className="analytics-grid"><FloatingCard className="analytics-chart-card"><div className="chart-card-heading"><div><p className="eyebrow">Quiz performance</p><h2>Your scores over time</h2></div><span className={comparison >= 0 ? 'success-text' : 'review-text'}>{comparison >= 0 ? '+' : ''}{comparison} pts vs class</span></div><div className="analytics-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={data.scoreTrend}><CartesianGrid stroke="rgba(255,255,255,0.1)" vertical={false} /><XAxis dataKey="topic" stroke="rgba(245,245,245,0.55)" tickLine={false} /><YAxis domain={[0, 100]} tickFormatter={(value) => `${value}%`} stroke="rgba(245,245,245,0.45)" tickLine={false} /><Tooltip /><Line type="monotone" dataKey="score" stroke="#00d9ff" strokeWidth={3} dot={{ fill: '#39ff14', r: 5 }} /></LineChart></ResponsiveContainer></div></FloatingCard><FloatingCard className="analytics-chart-card"><div className="chart-card-heading"><div><p className="eyebrow">Time invested</p><h2>Minutes by topic</h2></div></div><div className="analytics-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={data.timeByTopic}><CartesianGrid stroke="rgba(255,255,255,0.1)" vertical={false} /><XAxis dataKey="topic" stroke="rgba(245,245,245,0.55)" tickLine={false} /><YAxis stroke="rgba(245,245,245,0.45)" tickLine={false} /><Tooltip /><Bar dataKey="seconds" name="Seconds" fill="#9d4edd" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer></div></FloatingCard></section><section className="analytics-grid lower"><FloatingCard><div className="chart-card-heading"><div><p className="eyebrow">Mastery map</p><h2>Topics at a glance</h2></div></div><div className="topic-status-list"><div className="topic-status-header"><span>Mastered</span><strong>{data.mastered.length} topics</strong></div>{data.mastered.map((topic) => <div className="topic-status-row mastered" key={topic.topic_slug}><span>✓ {label(topic.topic_slug)}</span><strong>{Math.round(topic.best_score)}%</strong></div>)}<div className="topic-status-header review-header"><span>Needs review</span><strong>{data.needingReview.length} topics</strong></div>{data.needingReview.map((topic) => <div className="topic-status-row needs-review" key={topic.topic_slug}><span>↻ {label(topic.topic_slug)}</span><strong>{Math.round(topic.best_score)}%</strong></div>)}</div></FloatingCard><FloatingCard><p className="eyebrow">Your next signal</p><h2>Small sessions, real lift.</h2><p className="muted analytics-encouragement">You are building consistency. Spend {Math.max(10, Math.round(data.estimatedMinutesRemaining / 10))} focused minutes on a review topic today, then run one experiment to make the idea stick.</p><a className="btn-primary analytics-action" href="#lesson-2">Continue learning <span>→</span></a></FloatingCard></section></div></main>;
}
