import React, { useEffect, useMemo, useState } from 'react';
import AnimatedBackground from '../components/AnimatedBackground';
import FloatingCard from '../components/FloatingCard';
import GlowingIcon from '../components/GlowingIcon';
import { useAuth } from '../context/AuthContext';
import FacultyStudentDetail from '../components/FacultyStudentDetail';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';
export default function FacultyPage() {
  const { session } = useAuth();
  const [overview, setOverview] = useState({ totalStudents: 0, completionPercent: 0, averageScore: 0, students: [], commonMisconceptions: [] });
  const [questions, setQuestions] = useState([]);
  const [message, setMessage] = useState('');
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [announcement, setAnnouncement] = useState('');
  const [draft, setDraft] = useState({ topic_slug: 'superposition', prompt: '', question_type: 'mcq', difficulty: 'standard', answer: '' });
  const headers = useMemo(() => ({ Authorization: `Bearer ${session?.accessToken}`, 'Content-Type': 'application/json' }), [session?.accessToken]);
  useEffect(() => { Promise.all([fetch(`${API_URL}/faculty/overview`, { headers }).then((response) => response.json()), fetch(`${API_URL}/faculty/questions`, { headers }).then((response) => response.json())]).then(([overviewBody, questionBody]) => { if (overviewBody.students) setOverview(overviewBody); if (questionBody.questions) setQuestions(questionBody.questions); }).catch(() => setMessage('Faculty data could not be loaded. Check your API connection.')); }, [headers]);
  async function saveQuestion(event) { event.preventDefault(); const response = await fetch(`${API_URL}/faculty/questions`, { method: 'POST', headers, body: JSON.stringify(draft) }); const body = await response.json(); if (response.ok) { setQuestions((current) => [body.question, ...current]); setDraft({ ...draft, prompt: '', answer: '' }); setMessage('Question added to your bank.'); } else setMessage(body.error || 'Question could not be saved.'); }
  async function sendAnnouncement(event) { event.preventDefault(); const response = await fetch(`${API_URL}/faculty/announcements`, { method: 'POST', headers, body: JSON.stringify({ message: announcement }) }); if (response.ok) { setAnnouncement(''); setMessage('Announcement broadcast to your class.'); } }
  async function downloadReport(format) { const response = await fetch(`${API_URL}/faculty/reports/progress.${format}`, { headers: { Authorization: `Bearer ${session?.accessToken}` } }); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `class-progress.${format}`; link.click(); URL.revokeObjectURL(url); }
  return <main className="faculty-page page-enter"><AnimatedBackground /><nav className="glass-nav faculty-nav"><a className="brand-mark" href="#learn"><GlowingIcon label="Back to dashboard">←</GlowingIcon> QUANTUM ATLAS</a><span className="role-badge">Faculty workspace</span><a className="text-button" href="#learn">Exit</a></nav><div className="faculty-content"><header className="faculty-hero"><div><p className="eyebrow">Teaching cockpit / Class signal</p><h1>Help your class <span className="text-gradient">go further.</span></h1><p className="muted">One clear view of progress, misconceptions, and the next useful intervention.</p></div><div className="report-actions"><button className="download-report" type="button" onClick={() => downloadReport('csv')}>CSV ↓</button><button className="download-report" type="button" onClick={() => downloadReport('pdf')}>PDF ↓</button></div></header><section className="faculty-stats"><FloatingCard><span className="muted">Total students</span><strong>{overview.totalStudents}</strong></FloatingCard><FloatingCard><span className="muted">Class completion</span><strong>{overview.completionPercent}%</strong><div className="progress-track"><div className="progress-fill" style={{ width: `${overview.completionPercent}%` }} /></div></FloatingCard><FloatingCard><span className="muted">Average quiz score</span><strong>{overview.averageScore}%</strong></FloatingCard></section>{selectedStudent && <FacultyStudentDetail student={selectedStudent} session={session} onClose={() => setSelectedStudent(null)} />}<section className="faculty-grid"><FloatingCard className="student-card"><div className="faculty-heading"><div><p className="eyebrow">Your class</p><h2>Student progress</h2></div><span className="muted">{overview.students.length} learners</span></div><div className="student-table"><div className="student-row table-head"><span>Learner</span><span>Completion</span><span>Last active</span></div>{overview.students.map((student) => <button className="student-row student-row-button" type="button" key={student.id} onClick={() => setSelectedStudent(student)}><span><strong>{student.display_name}</strong><small>{student.email}</small></span><span><b>{student.completion_percent}%</b><i className="mini-progress"><em style={{ width: `${student.completion_percent}%` }} /></i></span><span className="muted">{student.last_active ? new Date(student.last_active).toLocaleDateString() : 'Not yet active'}</span></button>)}</div></FloatingCard><FloatingCard className="misconception-card"><p className="eyebrow">Cohort analytics</p><h2>Common misconceptions</h2>{overview.commonMisconceptions.map((item) => <div className="misconception-row" key={item.misconception_key}><span>{item.misconception_key.replaceAll('-', ' ')}</span><strong>{item.occurrences}</strong></div>)}</FloatingCard></section><section className="faculty-grid"><FloatingCard><div className="faculty-heading"><div><p className="eyebrow">Content studio</p><h2>Question bank</h2></div><span className="muted">{questions.length} questions</span></div><div className="question-list">{questions.map((question) => <div className="question-row" key={question.id}><span>{question.prompt}</span><small>{question.topic_slug} · {question.difficulty}</small></div>)}</div><form className="question-form" onSubmit={saveQuestion}><input placeholder="Topic slug" value={draft.topic_slug} onChange={(event) => setDraft({ ...draft, topic_slug: event.target.value })} /><input placeholder="Question prompt" value={draft.prompt} onChange={(event) => setDraft({ ...draft, prompt: event.target.value })} required /><select value={draft.question_type} onChange={(event) => setDraft({ ...draft, question_type: event.target.value })}><option value="mcq">Multiple choice</option><option value="probability">Probability</option><option value="circuit">Circuit build</option></select><select value={draft.difficulty} onChange={(event) => setDraft({ ...draft, difficulty: event.target.value })}><option value="easy">Easy</option><option value="standard">Standard</option><option value="hard">Hard</option></select><input placeholder="Correct answer" value={draft.answer} onChange={(event) => setDraft({ ...draft, answer: event.target.value })} /><button className="btn-primary" type="submit">Add question <span>+</span></button></form></FloatingCard><FloatingCard className="announcement-card"><p className="eyebrow">Class communication</p><h2>Broadcast announcement</h2><form onSubmit={sendAnnouncement}><textarea value={announcement} onChange={(event) => setAnnouncement(event.target.value)} placeholder="Share a nudge, deadline, or discovery..." rows="5" required /><button className="btn-primary" type="submit">Send to students <span>→</span></button></form>{message && <p className="success-text" role="status">{message}</p>}</FloatingCard></section></div></main>;
}
